CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shops (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL UNIQUE REFERENCES users(id), status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), category TEXT NOT NULL, active INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS variants (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), shop_id TEXT NOT NULL REFERENCES shops(id), stock BIGINT NOT NULL CHECK(stock>=0), price BIGINT NOT NULL CHECK(price>0), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at BIGINT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), purpose TEXT NOT NULL, expires_at BIGINT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS addresses (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS carts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wishlists (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES products(id), payload TEXT NOT NULL, UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS vouchers (id TEXT PRIMARY KEY, shop_id TEXT REFERENCES shops(id), code TEXT NOT NULL UNIQUE, active INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checkouts (id TEXT PRIMARY KEY, buyer_id TEXT NOT NULL REFERENCES users(id), idem_key TEXT NOT NULL, order_code BIGINT NOT NULL UNIQUE, status TEXT NOT NULL, expires_at BIGINT NOT NULL, payload TEXT NOT NULL, UNIQUE(buyer_id,idem_key));
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, buyer_id TEXT NOT NULL REFERENCES users(id), shop_id TEXT NOT NULL REFERENCES shops(id), checkout_id TEXT NOT NULL REFERENCES checkouts(id), status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), variant_id TEXT NOT NULL REFERENCES variants(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS redemptions (id TEXT PRIMARY KEY, voucher_id TEXT NOT NULL REFERENCES vouchers(id), checkout_id TEXT NOT NULL REFERENCES checkouts(id), payload TEXT NOT NULL, UNIQUE(voucher_id,checkout_id));
CREATE TABLE IF NOT EXISTS payment_events (id TEXT PRIMARY KEY, checkout_id TEXT NOT NULL REFERENCES checkouts(id), provider_ref TEXT NOT NULL UNIQUE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS returns (id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), buyer_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS refunds (id TEXT PRIMARY KEY, order_id TEXT REFERENCES orders(id), checkout_id TEXT NOT NULL REFERENCES checkouts(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, buyer_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES products(id), order_item_id TEXT NOT NULL UNIQUE REFERENCES order_items(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, buyer_id TEXT NOT NULL REFERENCES users(id), shop_id TEXT NOT NULL REFERENCES shops(id), payload TEXT NOT NULL, UNIQUE(buyer_id,shop_id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), sender_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS products_shop ON products(shop_id, active);
CREATE INDEX IF NOT EXISTS orders_buyer ON orders(buyer_id);
CREATE INDEX IF NOT EXISTS orders_shop ON orders(shop_id,status);
CREATE INDEX IF NOT EXISTS orders_checkout ON orders(checkout_id);
CREATE INDEX IF NOT EXISTS checkouts_expiry ON checkouts(status,expires_at);
CREATE INDEX IF NOT EXISTS variants_product ON variants(product_id);
CREATE INDEX IF NOT EXISTS messages_conversation ON messages(conversation_id);
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id);
CREATE INDEX IF NOT EXISTS reviews_product ON reviews(product_id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS outbox_status ON outbox(status);
